    public async ValueTask<bool> AuthorizeGenerationAsync(BaseSession session,BaseInstalledSubjectRetirementConsumer installed,CancellationToken cancellationToken)
    {
        if(!AudienceAllows(installed.Definition.Audience,session.Principal))return false;
        BaseGeneratedSubjectRegistration? contract=contracts.Find(installed.Lifecycle.Definition.ContractId,installed.Lifecycle.Definition.ContractVersion);
        if(contract is null)return false;
        OperationContext operation=session.Operation(BaseOperationKind.SubjectRetirementAcknowledge,installed.Definition.ConsumerId);
        var resource=new CollectionDefinition{Id=installed.Definition.ConsumerId,Name=installed.Definition.ConsumerId,Kind=BaseCollectionKinds.Custom,SchemaMode=SchemaMode.Strict,UnknownFields=UnknownFieldPolicy.Reject,System=true,SystemOwnerModuleId=installed.Definition.OwningModuleId};
        OperationResult<BasePolicyEvaluation> authorization=await policy.EvaluateWriteAsync(new(){Principal=session.Principal,Operation=operation,Collection=resource,ResourceKind=PolicyResourceKind.SubjectLifecycle},cancellationToken).ConfigureAwait(false);
        if(!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(authorization,installed.Definition.AcknowledgementGrantId,installed.Definition.OwningModuleId,installed.Definition.ConsumerId,contract.Definition.Id,contract.Definition.Version,session.Principal,operation))return false;
        OperationContext fixedOperation=session.Operation(BaseOperationKind.SubjectRetirementAcknowledge,FixedAcknowledgementGrant);
        OperationResult<BasePolicyEvaluation> fixedAuthorization=await policy.EvaluateWriteAsync(new(){Principal=session.Principal,Operation=fixedOperation,Collection=resource,ResourceKind=PolicyResourceKind.SubjectLifecycle},cancellationToken).ConfigureAwait(false);
        return BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(fixedAuthorization,FixedAcknowledgementGrant,installed.Definition.OwningModuleId,FixedAcknowledgementGrant,contract.Definition.Id,contract.Definition.Version,session.Principal,fixedOperation);
    }

