    public async ValueTask<BaseResult<BaseSubjectAcknowledgementResult>> AcknowledgeAsync(BaseSession session,BaseInstalledSubjectRetirementConsumer installed,ReadOnlyMemory<byte> evidence,BaseSubjectRetirementParticipation participation,BaseSubjectAcknowledgementDisposition disposition,BaseMutationRequestIdentity identity,CancellationToken cancellationToken)
