        if(!BaseSystemCollectionGate.HasExactSubjectLifecycleGrant(authorization,installed.Definition.AcknowledgementGrantId,installed.Definition.OwningModuleId,installed.Definition.ConsumerId,payload.ContractId,payload.ContractVersion,session.Principal,operation))return Failure<BaseSubjectAcknowledgementResult>(OperationStatus.PolicyDenied,BaseSubjectRetirementErrorCodes.Unauthorized,ErrorCategory.Authorization);
        OperationContext fixedOperation=session.Operation(BaseOperationKind.SubjectRetirementAcknowledge,FixedAcknowledgementGrant);OperationResult<BasePolicyEvaluation> fixedAuthorization=await policy.EvaluateWriteAsync(new(){Principal=session.Principal,Operation=fixedOperation,Collection=resource,ResourceKind=PolicyResourceKind.SubjectLifecycle},cancellationToken).ConfigureAwait(false);
